SourceCode.Declaration:
/// <summary>
/// The <c>METWorkflowWorkItemActionManager_Extension</c> class manages validation if bulk workflow selected is set to yes.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(classStr(WorkflowWorkItemActionManager))]
final class METWorkflowWorkItemActionManager_Extension
{
}

Method.Source:
/// <summary>
/// Prompts for action dialog and performs the workflow work item action.
/// </summary>
/// <exception cref="M:Exception::Error">
/// Could not find the workflow work item action for the selected menu item.
/// </exception>
protected void runWorkflowWorkItemAction()
{
    CustInvoiceTable        custInvoiceTable;
    WorkflowWorkItemTable   workflowWorkItemTable = this.parmWorkflowWorkItem();
    Args                    args = this.parmArgs();

    if (workflowWorkItemTable && args.record() is CustInvoiceTable)
    {
        select firstonly METBulkWorkflowSelected from custInvoiceTable
            where custInvoiceTable.RecId == workflowWorkItemTable.RefRecId;

        if (custInvoiceTable.METBulkWorkflowSelected)
        {
            throw Error("@MET:METFTIBulkWFSelectedValid");
        }
    }

    next runWorkflowWorkItemAction();
}
